// PWA manifest. Next.js serves this at /manifest.webmanifest and the
// browser uses it when the user adds the site to their home screen.
// The icon URLs resolve to the images generated by /app/icon.tsx — the
// "any" purpose covers the regular launcher icon; "maskable" tells
// Android it can crop safely for adaptive icons.

import type { MetadataRoute } from "next";

export default function manifest(): MetadataRoute.Manifest {
  return {
    name: "Sphere of Kings",
    short_name: "Sphere of Kings",
    description:
      "Spherical strategy games — Royal Checkers, Imperial Kings, and more. The companion app to the Sphere of Kings 7-in-1 board game.",
    start_url: "/",
    scope: "/",
    display: "standalone",
    orientation: "portrait",
    background_color: "#0a0806",
    theme_color: "#c9a227",
    icons: [
      {
        src: "/icon",
        sizes: "512x512",
        type: "image/png",
        purpose: "any",
      },
      {
        src: "/icon",
        sizes: "512x512",
        type: "image/png",
        purpose: "maskable",
      },
      {
        src: "/apple-icon",
        sizes: "180x180",
        type: "image/png",
      },
    ],
  };
}
